// Form label -> model id. Any id from GET /v1/models works.
const MODELS = {
  'Claude Sonnet 5.5': 'claude-sonnet-5-5',
  'Claude Haiku 5.5': 'claude-haiku-5-5',
  'GPT-5.5': 'gpt-5.5',
  'GPT-6 Luna': 'gpt-6-luna',
  'Gemini 4 Argon': 'gemini-4-argon',
  'Gemini 3.8 Flash': 'gemini-3.8-flash',
  'DeepSeek V4.1 Flash': 'deepseek-v4.1-flash',
  'Qwen3.8 Max': 'qwen3.8-max',
  'Grok 4.6': 'grok-4.6',
  'GLM-5.3': 'glm-5.3',
};

const form = $input.first().json;
const picked = Array.isArray(form['Models']) ? form['Models'] : [form['Models']];
const messages = [];
if ((form['System message'] || '').trim()) messages.push({ role: 'system', content: form['System message'].trim() });
messages.push({ role: 'user', content: form['Prompt'] });

return picked.filter((label) => MODELS[label]).map((label) => ({
  json: {
    label,
    body: { model: MODELS[label], max_tokens: Number(form['Output limit (tokens)']) || 2000, messages },
  },
}));

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const reqs = $('One item per model').all();
const answers = $('Ask each model').all();
const records = $input.all();
const form = $('Comparison form').first().json;

const rows = reqs.map((r, i) => {
  const a = answers[i] ? answers[i].json : {};
  const rec = (records[i] && records[i].json && records[i].json.data) || {};
  const text = a.body && a.body.choices && a.body.choices[0] && a.body.choices[0].message ? a.body.choices[0].message.content : null;
  const err = text == null ? ((a.error && (a.error.message || a.error)) || 'No answer') : null;
  const seconds = rec.created_at && rec.completed_at ? (rec.completed_at - rec.created_at) / 1000 : null;
  const usage = rec.usage || {};
  return {
    label: r.json.label, model: r.json.body.model, text, err, seconds,
    cost: typeof rec.credits === 'number' ? rec.credits : null,
    input: usage.input_tokens, output: usage.output_tokens,
    stop: a.body && a.body.choices && a.body.choices[0] ? a.body.choices[0].finish_reason : null,
  };
});

const ok = rows.filter((r) => !r.err);
const fastest = ok.filter((r) => r.seconds != null).sort((x, y) => x.seconds - y.seconds)[0];
const costs = ok.filter((r) => r.cost != null).map((r) => r.cost);
const lowestCost = costs.length ? Math.min(...costs) : null;  // ties all get the badge
const total = rows.reduce((s, r) => s + (r.cost || 0), 0);
const badge = (r) => [r === fastest ? '<span class="b">fastest</span>' : '', (r.cost != null && r.cost === lowestCost) ? '<span class="b">lowest cost</span>' : ''].join(' ');

const table = rows.map((r) => `<tr><td><b>${esc(r.label)}</b><br><span class="meta">${esc(r.model)}</span> ${badge(r)}</td>
<td>${r.err ? '—' : (r.seconds != null ? r.seconds.toFixed(1) + ' s' : '?')}</td>
<td>${r.err ? '—' : `${r.input ?? '?'} / ${r.output ?? '?'}`}</td>
<td>${r.err ? '$0 (failed)' : (r.cost != null ? '$' + r.cost.toFixed(4) : '?')}</td></tr>`).join('');

const cards = rows.map((r) => `<details ${r.err ? '' : 'open'}><summary><b>${esc(r.label)}</b> ${badge(r)}${r.stop === 'length' ? ' <span class="meta">(stopped at the output limit)</span>' : ''}</summary>
<div class="ans">${r.err ? '<span class="err">' + esc(r.err) + '</span>' : esc(r.text)}</div></details>`).join('');

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f5f5f4;color:#1c1917;margin:0;padding:32px 16px}
.card{max-width:960px;margin:0 auto;background:#fff;border:1px solid #e7e5e4;border-radius:16px;padding:24px}
table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e7e5e4;vertical-align:top}
.meta{color:#78716c;font-size:12px}.b{display:inline-block;margin-top:4px;padding:2px 8px;border-radius:999px;background:#ecfccb;color:#3f6212;font-size:12px}
details{border:1px solid #e7e5e4;border-radius:12px;padding:12px;margin:12px 0}summary{cursor:pointer}
.ans{white-space:pre-wrap;margin-top:10px;line-height:1.55}.err{color:#b91c1c}.prompt{white-space:pre-wrap;background:#fafaf9;border:1px solid #e7e5e4;border-radius:10px;padding:12px}
.btn{display:inline-block;margin-top:16px;padding:9px 16px;border-radius:10px;background:#1c1917;color:#fff;text-decoration:none}</style></head>
<body><div class="card"><h2>Model comparison</h2>
<div class="prompt">${esc(form['Prompt'])}</div>
<table><thead><tr><th>Model</th><th>Time</th><th>Tokens in / out</th><th>Charged</th></tr></thead><tbody>${table}</tbody></table>
<p class="meta">Time is measured on the server from request to last token. Charged is the exact amount from GET /v1/records/{id}; failed calls are not charged. Total: $${total.toFixed(4)}.</p>
${cards}
<a class="btn" href="/form/compare-models">Compare again</a></div></body></html>`;

return [{ json: { html } }];
